    n = draw(st.integers(7, 12))
    kind = draw(st.integers(0, 4))
    if kind == 0:
        # all equal values
        v = draw(st.integers(1, 5))
        nums = [v] * n
    elif kind == 1:
        # small value pool with many duplicates and coincidences
        nums = draw(st.lists(st.sampled_from([1, 2, 3, 4, 6, 8, 12]), min_size=n, max_size=n))
    elif kind == 2:
        # sorted ascending
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
    elif kind == 3:
        # sorted descending
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
    else:
        # general small values, including extremes of the range (scaled down)
        nums = draw(st.lists(st.one_of(st.just(1), st.just(1000), st.integers(1, 10)),
